//! Independent high-precision regression vectors for the special functions.
//!
//! Two independent oracles are replayed through the same checks: the Python
//! `decimal` fixture (`fixtures/special-golden-v1.json`, 100 digits, exact
//! special-angle identities) and the Wolfram Engine fixture
//! (`fixtures/special-golden-wolfram-v1.json`, generated by
//! `wolfram/special_golden.wls` at 50 digits).  Values are stored as decimal
//! strings so the provenance is not lost to JSON's binary64 parser before
//! this test performs the comparison.

use serde::Deserialize;
use sonium_wave::special::{
    associated_legendre, legendre_polynomials, legendre_polynomials_derivative, spherical_bessel_j,
    spherical_bessel_j_derivative, spherical_bessel_y, spherical_bessel_y_derivative,
    spherical_hankel_first_kind, try_associated_legendre, try_legendre_polynomials,
    try_legendre_polynomials_derivative, try_spherical_bessel_j, try_spherical_bessel_j_batch_into,
    try_spherical_bessel_j_derivative, try_spherical_bessel_y, try_spherical_bessel_y_derivative,
    try_spherical_hankel_first_kind,
};

const DECIMAL_FIXTURE: &str = include_str!("../fixtures/special-golden-v1.json");
const WOLFRAM_FIXTURE: &str = include_str!("../fixtures/special-golden-wolfram-v1.json");
const RELATIVE_TOLERANCE: f64 = 5e-13;

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    precision_digits: u32,
    generator: String,
    spherical: Vec<SphericalCase>,
    legendre: Vec<LegendreCase>,
}

#[derive(Debug, Deserialize)]
struct SphericalCase {
    name: String,
    x: String,
    j: Vec<String>,
    y: Vec<String>,
    j_derivative: Vec<String>,
    y_derivative: Vec<String>,
    /// Wolfram H1 = j + i y reference parts (absent from the decimal oracle).
    #[serde(default)]
    h1_re: Vec<String>,
    #[serde(default)]
    h1_im: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct LegendreCase {
    name: String,
    x: String,
    p: Vec<String>,
    derivative: Vec<String>,
    associated_m: usize,
    associated: Vec<String>,
}

fn assert_close(actual: &[f64], expected: &[String], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label} length");
    for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
        let expected = expected.parse::<f64>().expect("fixture value is a decimal");
        let scale = expected.abs().max(1.0);
        assert!(
            (actual - expected).abs() <= RELATIVE_TOLERANCE * scale,
            "{label}[{index}] = {actual:.17e}, expected {expected:.17e}"
        );
    }
}

fn parse_decimal_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(DECIMAL_FIXTURE).expect("valid special-function fixture");
    assert_eq!(fixture.schema, "sonium-wave.special-golden.v1");
    assert_eq!(fixture.precision_digits, 100);
    assert!(fixture.generator.contains("Python decimal"));
    fixture
}

fn parse_wolfram_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(WOLFRAM_FIXTURE).expect("valid Wolfram special-function fixture");
    assert_eq!(fixture.schema, "sonium-wave.special-golden-wolfram.v1");
    assert_eq!(fixture.precision_digits, 50);
    assert!(fixture.generator.contains("Wolfram Engine"));
    fixture
}

fn check_spherical(fixture: &Fixture) {
    for case in &fixture.spherical {
        let x = case
            .x
            .parse::<f64>()
            .expect("fixture argument is a decimal");
        assert_close(
            &spherical_bessel_j(case.j.len(), x),
            &case.j,
            &format!("{} j", case.name),
        );
        assert_close(
            &spherical_bessel_y(case.y.len(), x),
            &case.y,
            &format!("{} y", case.name),
        );
        assert_close(
            &spherical_bessel_j_derivative(case.j_derivative.len(), x),
            &case.j_derivative,
            &format!("{} j'", case.name),
        );
        assert_close(
            &spherical_bessel_y_derivative(case.y_derivative.len(), x),
            &case.y_derivative,
            &format!("{} y'", case.name),
        );

        let hankel = spherical_hankel_first_kind(case.j.len(), x, 1.0);
        assert_close(
            &hankel.iter().map(|value| value.re).collect::<Vec<_>>(),
            &case.j,
            &format!("{} h.re", case.name),
        );
        assert_close(
            &hankel.iter().map(|value| value.im).collect::<Vec<_>>(),
            &case.y,
            &format!("{} h.im", case.name),
        );

        assert_close(
            &try_spherical_bessel_j(case.j.len(), x).expect("checked j vector"),
            &case.j,
            &format!("{} checked j", case.name),
        );
        assert_close(
            &try_spherical_bessel_y(case.y.len(), x).expect("checked y vector"),
            &case.y,
            &format!("{} checked y", case.name),
        );
        assert_close(
            &try_spherical_bessel_j_derivative(case.j_derivative.len(), x)
                .expect("checked j derivative vector"),
            &case.j_derivative,
            &format!("{} checked j'", case.name),
        );
        assert_close(
            &try_spherical_bessel_y_derivative(case.y_derivative.len(), x)
                .expect("checked y derivative vector"),
            &case.y_derivative,
            &format!("{} checked y'", case.name),
        );
        let checked_hankel =
            try_spherical_hankel_first_kind(case.j.len(), x, 1.0).expect("checked Hankel vector");
        assert_close(
            &checked_hankel
                .iter()
                .map(|value| value.re)
                .collect::<Vec<_>>(),
            &case.j,
            &format!("{} checked h.re", case.name),
        );
    }
}

#[test]
fn spherical_functions_match_independent_decimal_vectors() {
    check_spherical(&parse_decimal_fixture());
}

#[test]
fn spherical_functions_match_wolfram_vectors() {
    let fixture = parse_wolfram_fixture();
    check_spherical(&fixture);
    check_wolfram_hankel(&fixture);
    check_wolfram_wronskian(&fixture);
}

/// Wolfram H1 = j + i y parts, computed independently of the Sonium
/// recurrence: both the real/imaginary packing and the values are checked.
fn check_wolfram_hankel(fixture: &Fixture) {
    for case in &fixture.spherical {
        assert_eq!(case.h1_re.len(), case.j.len(), "{} h1 length", case.name);
        let x = case
            .x
            .parse::<f64>()
            .expect("fixture argument is a decimal");
        let hankel = spherical_hankel_first_kind(case.j.len(), x, 1.0);
        assert_close(
            &hankel.iter().map(|value| value.re).collect::<Vec<_>>(),
            &case.h1_re,
            &format!("{} wolfram h1.re", case.name),
        );
        assert_close(
            &hankel.iter().map(|value| value.im).collect::<Vec<_>>(),
            &case.h1_im,
            &format!("{} wolfram h1.im", case.name),
        );
    }
}

/// Wronskian self-consistency of the Wolfram oracle itself:
/// j_n·y_n' − j_n'·y_n = 1/x². This catches generator bugs (wrong branch,
/// recurrence direction, derivative convention) before trusting the oracle.
/// Restricted to n ≤ 2: at high orders and small x the two products cancel
/// far above the result and binary64 cannot resolve the difference.
fn check_wolfram_wronskian(fixture: &Fixture) {
    for case in &fixture.spherical {
        let x = case
            .x
            .parse::<f64>()
            .expect("fixture argument is a decimal");
        let expected = 1.0 / (x * x);
        for n in 0..3.min(case.j.len()) {
            let j: f64 = case.j[n].parse().expect("fixture value is a decimal");
            let y: f64 = case.y[n].parse().expect("fixture value is a decimal");
            let jd: f64 = case.j_derivative[n]
                .parse()
                .expect("fixture value is a decimal");
            let yd: f64 = case.y_derivative[n]
                .parse()
                .expect("fixture value is a decimal");
            let wronskian = j * yd - jd * y;
            assert!(
                (wronskian - expected).abs() <= 1e-9 * expected.abs().max(1.0),
                "{} wronskian n={n}: {wronskian:.17e} != 1/x^2 = {expected:.17e}",
                case.name,
            );
        }
    }
}

fn check_bessel_batch(fixture: &Fixture) {
    let order = fixture
        .spherical
        .first()
        .expect("fixture contains spherical cases")
        .j
        .len();
    assert!(fixture.spherical.iter().all(|case| case.j.len() == order));
    let arguments = fixture
        .spherical
        .iter()
        .map(|case| {
            case.x
                .parse::<f64>()
                .expect("fixture argument is a decimal")
        })
        .collect::<Vec<_>>();
    let mut output = vec![0.0; arguments.len() * order];
    let mut workspace = Vec::new();

    try_spherical_bessel_j_batch_into(order, &arguments, &mut output, &mut workspace)
        .expect("checked batch recurrence");
    for (case, row) in fixture.spherical.iter().zip(output.chunks_exact(order)) {
        assert_close(row, &case.j, &format!("{} checked batch j", case.name));
    }
}

#[test]
fn spherical_bessel_batch_matches_independent_decimal_vectors() {
    check_bessel_batch(&parse_decimal_fixture());
}

#[test]
fn spherical_bessel_batch_matches_wolfram_vectors() {
    let fixture = parse_wolfram_fixture();
    assert!(
        fixture.spherical.iter().all(|case| case.j.len() == 14),
        "wolfram fixture carries orders 0..=13 in every case"
    );
    check_bessel_batch(&fixture);
}

fn check_legendre(fixture: &Fixture) {
    for case in &fixture.legendre {
        let x = case
            .x
            .parse::<f64>()
            .expect("fixture argument is a decimal");
        assert_close(
            &legendre_polynomials(case.p.len(), x),
            &case.p,
            &format!("{} P", case.name),
        );
        assert_close(
            &legendre_polynomials_derivative(case.derivative.len(), x),
            &case.derivative,
            &format!("{} P'", case.name),
        );
        assert_close(
            &associated_legendre(
                case.associated.len() + case.associated_m - 1,
                case.associated_m,
                x,
            ),
            &case.associated,
            &format!("{} P^{}", case.name, case.associated_m),
        );

        assert_close(
            &try_legendre_polynomials(case.p.len(), x).expect("checked Legendre vector"),
            &case.p,
            &format!("{} checked P", case.name),
        );
        assert_close(
            &try_legendre_polynomials_derivative(case.derivative.len(), x)
                .expect("checked Legendre derivative vector"),
            &case.derivative,
            &format!("{} checked P'", case.name),
        );
        assert_close(
            &try_associated_legendre(
                case.associated.len() + case.associated_m - 1,
                case.associated_m,
                x,
            )
            .expect("checked associated Legendre vector"),
            &case.associated,
            &format!("{} checked P^{}", case.name, case.associated_m),
        );
    }
}

#[test]
fn legendre_functions_match_independent_decimal_vectors() {
    check_legendre(&parse_decimal_fixture());
}

#[test]
fn legendre_functions_match_wolfram_vectors() {
    check_legendre(&parse_wolfram_fixture());
}
